          return;
        }

        if (key === "]") {
          switchRun(-1);
          return;
        }

        if (/^[1-6]$/.test(key)) {
          switchToRecentRun(Number(key) - 1);
          return;
        }

        if (key === "c") {
          cancelRun();
          return;
        }

        if (key === "p") {
          pauseOrResumeRun();
          return;
        }

        if (key === "f") {
          retryFailedStories();
          return;
        }

        if (key === "s") {
          retrySelectedStory();
          return;
        }

        if (key === "m") {
          retryMerge();
          return;
        }

        if (key === "o") {
          setPane("output");
          return;
        }

        if (key === "t") {
          setPane("story");
          return;
        }

        if (key === "v") {
          setPane("run");
          return;
        }

        if (key === "e") {
          setPane("events");
          return;
        }

        if (key === "l") {
          openRunLog();
          return;
        }

        if (key === "g") {
          openRunCommits();
          return;
        }
      },

      render(width: number): string[] {
        const safeWidth = Math.max(60, width);
        const selectedStory = collection.stories.find((story) => story.id === selectedStoryId);
        const specSlug = extractSpecSlug(payload?.run.spec_path);
        const counts = countStatuses(collection.stories);
        const failedStories = collection.stories.filter((story) => normalizeStatus(story.status) === "failed");
        const currentStory = payload?.runState?.currentStory ?? collection.stories.find((story) => normalizeStatus(story.status) === "running")?.id ?? null;
        const activeWave = findActiveWave(collection.waves);
        const activeWaveSummary = activeWave ? summarizeWaveProgress(activeWave.stories) : null;
        const header = [
          truncate(`Rorca Run Cockpit — Run ${runId}`, safeWidth),
          truncate(
            `Status ${payload ? formatStatus(payload.run.status) : "loading"} • Workspace ${workspaceLabel} • Spec ${specSlug} • Started ${payload?.run.started_at ? timeAgo(payload.run.started_at) : "unknown"}`,
            safeWidth,
          ),
          truncate(
            `Stories ${collection.stories.length} • ${counts.get("running") ?? 0} running • ${counts.get("passed") ?? 0} passed • ${counts.get("failed") ?? 0} failed • Tokens ${formatTokens(payload?.tokenSummary?.inputTokens)} / ${formatTokens(payload?.tokenSummary?.outputTokens)} • ${formatCurrency(payload?.tokenSummary?.totalCostUsd)}`,
            safeWidth,
          ),
          truncate(
            failedStories.length > 0
              ? `Attention: ${failedStories.length} failed • ${failedStories.slice(0, 2).map((story) => story.id).join(", ")}${failedStories.length > 2 ? " …" : ""}`
              : currentStory
                ? `Active story: ${currentStory}`
                : payload?.run.merge_status === "failed"
                  ? "Attention: auto-merge failed — press m to retry merge"
                  : "No active alerts.",
            safeWidth,
          ),
          truncate(
            activeWave && activeWaveSummary
              ? `Wave ${activeWave.index + 1}/${Math.max(1, collection.waves.length)} • ${activeWaveSummary.done}/${activeWaveSummary.total} complete • ${activeWaveSummary.running} running • ${activeWaveSummary.pending} waiting`
              : "Wave view unavailable.",
            safeWidth,
          ),
          "",
        ];

        const leftLines = renderStoryList(collection.stories, collection.waves, selectedStoryId, Math.max(24, Math.floor(safeWidth * 0.43)));
        const rightWidth = safeWidth >= 100 ? Math.max(28, safeWidth - Math.max(28, Math.floor(safeWidth * 0.43)) - 3) : safeWidth;
        const rightLines =
          pane === "output"
            ? buildOutputPane(selectedStory, selectedOutput, selectedOutputError, rightWidth)
            : pane === "story"
              ? buildStoryPane(selectedStory, payload?.runState, selectedOutput, rightWidth)
              : pane === "run"
                ? buildRunPane(payload, workspaceLabel, collection.stories, collection.waves, rightWidth, workspaceRuns, workspaceRunsError)
                : pane === "events"
                  ? buildEventsPane(payload, collection.stories, rightWidth)
                  : pane === "log"
                    ? buildLogPane(runLogLines, runLogError, rightWidth)
                    : buildCommitsPane(runCommits, runCommitsBranchName, runCommitsError, rightWidth);

        const body = safeWidth >= 100
          ? renderBodyColumns(leftLines, rightLines, safeWidth)
          : [
              ...leftLines.map((line) => truncate(line, safeWidth)),
              "",
              ...rightLines.map((line) => truncate(line, safeWidth)),
            ];

        const controls: string[] = [
          "j/k move",
          "u active",
          "x next failed",
          "n next ready",
          "b next blocked",
          "a active wave",
          ",/. waves",
          "tab cycle panes",
          "o output",
          "t story",
          "v run",
          "e events",
          "[ older",
          "] newer",
          "1-6 recent",
          "l log",
          "g commits",
          "r refresh",
          "q close",
        ];
        if (payload && isPausableRun(payload.run.status)) {
          controls.push("p pause");
        } else if (payload && isResumableRun(payload.run.status)) {
          controls.push("p resume");
        }
        if (payload && isCancellableRun(payload.run.status)) {
          controls.push("c cancel");
        }
        if (payload && isRetryableRun(payload.run.status)) {
          controls.push("f retry failed");
          if (isRetryableStory(selectedStory)) {
            controls.push("s retry story");
          }
        }
        if (canRetryMerge(payload)) {
          controls.push("m retry merge");
        }

        return [
          ...header,
          ...body,
          "",
          truncate(statusLine, safeWidth),
          truncate(controls.join(" • "), safeWidth),
        ];
      },

      invalidate() {
        // Stateless rendering.
      },
    };
  });
}

#!/usr/bin/env python3
"""Validator for the Rorca Pi extension safety envelope.

This intentionally focuses on the terminal-corruption class of regressions that
previous embedded Rorca views caused inside Pi.

It fails when Pi-native extension files still directly manipulate stdin/stdout,
raw mode, or terminal reset behavior.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path


EXT_DIR = Path.home() / ".pi" / "agent" / "extensions" / "rorca"
SCAN_GLOBS = ["index.ts", "tui/*.ts", "lib/*.ts"]
IGNORE_FRAGMENTS = [".bak-", ".disabled-"]
RULES = [
    {
        "id": "no-process-stdin",
        "pattern": re.compile(r"\bprocess\.stdin\b"),
        "message": "Pi-native extension code must not directly manipulate process.stdin.",
    },
    {
        "id": "no-process-stdout",
        "pattern": re.compile(r"\bprocess\.stdout\b"),
        "message": "Pi-native extension code must not directly manipulate process.stdout.",
    },
    {
        "id": "no-raw-mode",
        "pattern": re.compile(r"\bsetRawMode\s*\("),
        "message": "Pi-native extension code must not toggle raw terminal mode.",
    },
    {
        "id": "no-restore-terminal-state",
        "pattern": re.compile(r"\brestoreTerminalState\s*\("),
        "message": "Pi-native extension code must not use terminal reset hacks in embedded views.",
    },
    {
        "id": "no-ansi-clear-screen",
        "pattern": re.compile(r"\\x1b\[(?:2J|H|7m|0m)"),
        "message": "Pi-native extension code must not rely on manual ANSI terminal painting.",
    },
]


def should_scan(path: Path) -> bool:
    return all(fragment not in path.name for fragment in IGNORE_FRAGMENTS)


def collect_files() -> list[Path]:
    files: list[Path] = []
    for pattern in SCAN_GLOBS:
        files.extend(sorted(EXT_DIR.glob(pattern)))
    return [path for path in files if path.is_file() and should_scan(path)]


def main() -> int:
    if not EXT_DIR.exists():
        print(json.dumps({"ok": False, "error": f"Extension directory not found: {EXT_DIR}"}, indent=2))
        return 2

    violations: list[dict[str, object]] = []
    scanned = 0

    for path in collect_files():
        scanned += 1
        text = path.read_text(encoding="utf-8")
        lines = text.splitlines()
        for rule in RULES:
            pattern = rule["pattern"]
            assert isinstance(pattern, re.Pattern)
            for line_no, line in enumerate(lines, start=1):
                if pattern.search(line):
                    violations.append(
                        {
                            "rule": rule["id"],
                            "file": str(path),
                            "line": line_no,
                            "message": rule["message"],
                            "snippet": line.strip(),
                        }
                    )

    payload = {
        "ok": not violations,
        "scannedFiles": scanned,
        "violations": violations,
    }
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0 if not violations else 1


if __name__ == "__main__":
    raise SystemExit(main())

